1. [package]
2. name = "vrl"
3. version = "0.6.0"
4. authors = ["Vector Contributors <vector@datadoghq.com>"]
5. edition = "2021"
6. license = "MPL-2.0"
7. description = "Vector Remap Language"
8. homepage = "https://vrl.dev/"
9. repository = "https://github.com/vectordotdev/vrl"
10. readme = "README.md"
11. keywords = ["vector", "datadog", "compiler"]
12. categories = ["compilers"]
13. 
14. [workspace]
15. members = [
16.   ".",
17.   "lib/cli",
18.   "lib/tests",
19.   "lib/fuzz"
20. ]
21. 
22. 
23. [features]
24. default = ["compiler", "value", "diagnostic", "path", "parser", "stdlib", "datadog", "core"]
25. 
26. # Main features (on by default)
27. compiler = ["diagnostic", "path", "parser", "value", "dep:paste", "dep:chrono", "dep:serde", "dep:regex", "dep:bytes", "dep:ordered-float", "dep:chrono-tz", "dep:snafu", "dep:tracing", "dep:thiserror", "dep:anymap", "dep:dyn-clone", "dep:indoc", "dep:thiserror", "dep:lalrpop-util"]
28. value = ["path", "dep:bytes", "dep:regex", "dep:ordered-float", "dep:chrono", "dep:serde_json"]
29. diagnostic = ["dep:codespan-reporting", "dep:termcolor"]
30. path = ["dep:once_cell", "dep:serde", "dep:snafu", "dep:regex"]
31. parser = ["path", "diagnostic", "dep:thiserror", "dep:ordered-float", "dep:lalrpop-util"]
32. core = ["value", "dep:snafu", "dep:nom"]
33. string_path = []
34. 
35. # Datadog related features (on by default)
36. datadog = ["datadog_filter", "datadog_grok", "datadog_search"]
37. datadog_filter = ["datadog_search", "dep:regex", "dep:dyn-clone"]
38. datadog_grok = ["value", "dep:nom", "dep:peeking_take_while", "dep:serde_json", "dep:onig", "dep:lalrpop-util", "dep:thiserror", "dep:chrono", "dep:chrono-tz", "dep:tracing"]
39. datadog_search = ["dep:pest", "dep:pest_derive", "dep:itertools", "dep:once_cell", "dep:regex"]
40. 
41. # Features that aren't used as often (default off)
42. cli = ["stdlib", "dep:serde_json", "dep:thiserror", "dep:clap", "dep:exitcode", "dep:webbrowser", "dep:rustyline", "dep:prettytable-rs"]
43. test_framework = ["compiler", "dep:prettydiff", "dep:serde_json", "dep:ansi_term"]
44. arbitrary = ["dep:quickcheck", "dep:arbitrary"]
45. lua = ["dep:mlua"]
46. 
47. # Internal testing utilities (used for benches)
48. test = ["string_path"]
49. 
50. # All stdlib functions
