1. //! Contains the main "Value" type for Vector and VRL, as well as helper methods.
2. 
3. mod convert;
4. mod crud;
5. mod display;
6. mod iter;
7. mod path;
8. mod regex;
9. 
10. #[cfg(any(test, feature = "arbitrary"))]
11. mod arbitrary;
12. #[cfg(any(test, feature = "lua"))]
13. mod lua;
14. mod serde;
15. 
16. use std::collections::BTreeMap;
17. 
18. pub use super::value::regex::ValueRegex;
19. use crate::path::ValuePath;
20. use bytes::{Bytes, BytesMut};
21. use chrono::{DateTime, SecondsFormat, Utc};
22. pub use iter::{IterItem, ValueIter};
23. use ordered_float::NotNan;
24. 
25. /// A boxed `std::error::Error`.
26. pub type StdError = Box<dyn std::error::Error + Send + Sync + 'static>;
27. 
28. /// The main value type used in Vector events, and VRL.
29. #[derive(Eq, PartialEq, Hash, Debug, Clone)]
30. pub enum Value {
31.     /// Bytes - usually representing a UTF8 String.
32.     Bytes(Bytes),
33. 
34.     /// Regex.
35.     /// When used in the context of Vector this is treated identically to Bytes. It has
36.     /// additional meaning in the context of VRL.
37.     Regex(ValueRegex),
38. 
39.     /// Integer.
40.     Integer(i64),
41. 
42.     /// Float - not NaN.
43.     Float(NotNan<f64>),
44. 
45.     /// Boolean.
46.     Boolean(bool),
47. 
48.     /// Timestamp (UTC).
49.     Timestamp(DateTime<Utc>),
50. 
51.     /// Object.
52.     Object(BTreeMap<String, Value>),
53. 
54.     /// Array.
55.     Array(Vec<Value>),
56. 
57.     /// Null.
58.     Null,
59. }
60. 
61. impl Value {
62.     /// Returns a string description of the value type
63.     pub const fn kind_str(&self) -> &str {
64.         match self {
65.             Self::Bytes(_) | Self::Regex(_) => "string",
66.             Self::Timestamp(_) => "timestamp",
67.             Self::Integer(_) => "integer",
68.             Self::Float(_) => "float",
69.             Self::Boolean(_) => "boolean",
70.             Self::Object(_) => "map",
71.             Self::Array(_) => "array",
72.             Self::Null => "null",
73.         }
74.     }
75. 
76.     /// Merges `incoming` value into self.
77.     ///
78.     /// Will concatenate `Bytes` and overwrite the rest value kinds.
79.     pub fn merge(&mut self, incoming: Self) {
80.         match (self, incoming) {
81.             (Self::Bytes(self_bytes), Self::Bytes(ref incoming)) => {
82.                 let mut bytes = BytesMut::with_capacity(self_bytes.len() + incoming.len());
83.                 bytes.extend_from_slice(&self_bytes[..]);
84.                 bytes.extend_from_slice(&incoming[..]);
85.                 *self_bytes = bytes.freeze();
86.             }
87.             (current, incoming) => *current = incoming,
88.         }
89.     }
90. 
91.     /// Return if the node is empty, that is, it is an array or map with no items.
92.     ///
93.     /// ```rust
94.     /// use vrl::value::Value;
95.     /// use std::collections::BTreeMap;
96.     /// use vrl::path;
97.     ///
98.     /// let val = Value::from(1);
99.     /// assert_eq!(val.is_empty(), false);
100.     ///
101.     /// let mut val = Value::from(Vec::<Value>::default());
102.     /// assert_eq!(val.is_empty(), true);
103.     /// val.insert(path!(0), 1);
104.     /// assert_eq!(val.is_empty(), false);
105.     /// val.insert(path!(3), 1);
106.     /// assert_eq!(val.is_empty(), false);
107.     ///
108.     /// let mut val = Value::from(BTreeMap::default());
109.     /// assert_eq!(val.is_empty(), true);
110.     /// val.insert("foo", 1);
111.     /// assert_eq!(val.is_empty(), false);
112.     /// val.insert("bar", 2);
113.     /// assert_eq!(val.is_empty(), false);
114.     /// ```
115.     pub fn is_empty(&self) -> bool {
116.         match &self {
117.             Self::Boolean(_)
118.             | Self::Bytes(_)
119.             | Self::Regex(_)
120.             | Self::Timestamp(_)
121.             | Self::Float(_)
122.             | Self::Integer(_) => false,
123.             Self::Null => true,
124.             Self::Object(v) => v.is_empty(),
125.             Self::Array(v) => v.is_empty(),
126.         }
127.     }
128. 
129.     /// Returns a reference to a field value specified by a path iter.
130.     #[allow(clippy::needless_pass_by_value)]
131.     pub fn insert<'a>(
132.         &mut self,
133.         path: impl ValuePath<'a>,
134.         insert_value: impl Into<Self>,
135.     ) -> Option<Self> {
136.         let insert_value = insert_value.into();
137.         let path_iter = path.segment_iter().peekable();
138. 
139.         crud::insert(self, (), path_iter, insert_value)
140.     }
141. 
142.     /// Removes field value specified by the given path and return its value.
143.     ///
144.     /// A special case worth mentioning: if there is a nested array and an item is removed
145.     /// from the middle of this array, then it is just replaced by `Value::Null`.
146.     #[allow(clippy::needless_pass_by_value)]
147.     pub fn remove<'a>(&mut self, path: impl ValuePath<'a>, prune: bool) -> Option<Self> {
148.         crud::remove(self, &(), path.segment_iter(), prune)
149.             .map(|(prev_value, _is_empty)| prev_value)
150.     }
151. 
152.     /// Returns a reference to a field value specified by a path iter.
153.     #[allow(clippy::needless_pass_by_value)]
154.     pub fn get<'a>(&self, path: impl ValuePath<'a>) -> Option<&Self> {
155.         crud::get(self, path.segment_iter())
156.     }
157. 
158.     /// Get a mutable borrow of the value by path
159.     #[allow(clippy::needless_pass_by_value)]
160.     pub fn get_mut<'a>(&mut self, path: impl ValuePath<'a>) -> Option<&mut Self> {
161.         crud::get_mut(self, path.segment_iter())
162.     }
163. 
164.     /// Determine if the lookup is contained within the value.
165.     pub fn contains<'a>(&self, path: impl ValuePath<'a>) -> bool {
166.         self.get(path).is_some()
167.     }
168. }
169. 
170. /// Converts a timestamp to a `String`.
171. #[must_use]
172. pub fn timestamp_to_string(timestamp: &DateTime<Utc>) -> String {
173.     timestamp.to_rfc3339_opts(SecondsFormat::AutoSi, true)
174. }
175. 
176. #[cfg(test)]
177. mod test {
178.     use crate::path;
179.     use crate::path::BorrowedSegment;
180.     use quickcheck::{QuickCheck, TestResult};
181. 
182.     use super::*;
183. 
184.     mod corner_cases {
185.         use super::*;
186. 
187.         #[test]
188.         fn remove_prune_map_with_map() {
189.             let mut value = Value::from(BTreeMap::default());
190.             let key = "foo.bar";
191.             let marker = Value::from(true);
192.             assert_eq!(value.insert(key, marker.clone()), None);
193.             // Since the `foo` map is now empty, this should get cleaned.
194.             assert_eq!(value.remove(key, true), Some(marker));
195.             assert!(!value.contains("foo"));
196.         }
197. 
198.         #[test]
199.         fn remove_prune_map_with_array() {
200.             let mut value = Value::from(BTreeMap::default());
201.             let key = "foo[0]";
202.             let marker = Value::from(true);
203.             assert_eq!(value.insert(key, marker.clone()), None);
204.             // Since the `foo` map is now empty, this should get cleaned.
205.             assert_eq!(value.remove(key, true), Some(marker));
206.             assert!(!value.contains("foo"));
207.         }
208. 
209.         #[test]
210.         fn remove_prune_array_with_map() {
211.             let mut value = Value::from(Vec::<Value>::default());
212.             let key = "[0].bar";
213.             let marker = Value::from(true);
214.             assert_eq!(value.insert(key, marker.clone()), None);
215.             // Since the `foo` map is now empty, this should get cleaned.
216.             assert_eq!(value.remove(key, true), Some(marker));
217.             assert!(!value.contains(path!(0)));
218.         }
219. 
220.         #[test]
221.         fn remove_prune_array_with_array() {
222.             let mut value = Value::from(Vec::<Value>::default());
223.             let key = "[0][0]";
224.             let marker = Value::from(true);
225.             assert_eq!(value.insert(key, marker.clone()), None);
226.             // Since the `foo` map is now empty, this should get cleaned.
227.             assert_eq!(value.remove(key, true), Some(marker));
228.             assert!(!value.contains(path!(0)));
229.         }
230.     }
231. 
232.     #[test]
233.     fn quickcheck_value() {
234.         fn inner(mut path: Vec<BorrowedSegment<'static>>) -> TestResult {
235.             let mut value = Value::from(BTreeMap::default());
236.             let mut marker = Value::from(true);
237. 
238.             // Push a field at the start of the path so the top level is a map.
239.             path.insert(0, BorrowedSegment::from("field"));
240. 
241.             assert_eq!(value.insert(&path, marker.clone()), None, "inserting value");
242.             assert_eq!(value.get(&path), Some(&marker), "retrieving value");
243.             assert_eq!(
244.                 value.get_mut(&path),
245.                 Some(&mut marker),
246.                 "retrieving mutable value"
247.             );
248. 
249.             assert_eq!(value.remove(&path, true), Some(marker), "removing value");
250. 
251.             TestResult::passed()
252.         }
253. 
254.         QuickCheck::new()
255.             .tests(100)
256.             .max_tests(200)
257.             .quickcheck(inner as fn(Vec<BorrowedSegment<'static>>) -> TestResult);
258.     }
259. }
