133. /// Syntactic sugar for creating a pre-parsed owned path.
134. ///
135. /// This allocates and will be slower than using `path!`. Prefer that when possible.
136. /// The return value must be borrowed to get a value that implements `Path`.
137. ///
138. /// Example: `owned_value_path!("foo", 4, "bar")` is the pre-parsed path of `foo[4].bar`
139. #[macro_export]
140. macro_rules! owned_value_path {
141.     ($($segment:expr),*) => {{
142.            $crate::path::OwnedValuePath::from(vec![$($crate::path::OwnedSegment::from($segment),)*])
143.     }};
