146. /// Used to pre-parse a path.
147. /// The return value (when borrowed) implements `Path` so it can be used directly.
148. /// This parses a value path, which is a path without a target prefix.
149. ///
150. /// See `parse_target_path` if the path contains a target prefix.
151. pub fn parse_value_path(path: &str) -> Result<OwnedValuePath, PathParseError> {
152.     JitValuePath::new(path)
153.         .to_owned_value_path()
154.         .map_err(|_| PathParseError::InvalidPathSyntax {
155.             path: path.to_owned(),
156.         })
