159. /// Used to pre-parse a path.
160. /// The return value (when borrowed) implements `Path` so it can be used directly.
161. /// This parses a target path, which is a path that contains a target prefix.
162. ///
163. /// See `parse_value_path` if the path doesn't contain a prefix.
164. pub fn parse_target_path(path: &str) -> Result<OwnedTargetPath, PathParseError> {
165.     let (prefix, value_path) = get_target_prefix(path);
166.     let value_path = parse_value_path(value_path)?;
167. 
168.     Ok(OwnedTargetPath {
169.         prefix,
170.         path: value_path,
