181. /// A path is simply the data describing how to look up a field from a value.
182. /// This should only be implemented for types that are very cheap to clone, such as references.
183. pub trait ValuePath<'a>: Clone {
184.     type Iter: Iterator<Item = BorrowedSegment<'a>> + Clone;
185. 
186.     /// Iterates over the raw "Borrowed" segments.
187.     fn segment_iter(&self) -> Self::Iter;
188. 
189.     fn concat<T: ValuePath<'a>>(&self, path: T) -> PathConcat<Self, T> {
190.         PathConcat {
191.             a: self.clone(),
192.             b: path,
193.         }
194.     }
195. 
196.     fn eq(&self, other: impl ValuePath<'a>) -> bool {
197.         self.segment_iter().eq(other.segment_iter())
198.     }
199. 
200.     fn can_start_with(&self, prefix: impl ValuePath<'a>) -> bool {
201.         let (self_path, prefix_path) = if let (Ok(self_path), Ok(prefix_path)) =
202.             (self.to_owned_value_path(), prefix.to_owned_value_path())
203.         {
204.             (self_path, prefix_path)
205.         } else {
206.             return false;
207.         };
208. 
209.         let mut self_segments = self_path.segments.into_iter();
210.         for prefix_segment in prefix_path.segments.iter() {
211.             match self_segments.next() {
212.                 None => return false,
213.                 Some(self_segment) => {
214.                     if !self_segment.can_start_with(prefix_segment) {
215.                         return false;
216.                     }
217.                 }
218.             }
219.         }
220.         true
221.     }
