223.     #[allow(clippy::result_unit_err)]
224.     fn to_owned_value_path(&self) -> Result<OwnedValuePath, ()> {
225.         let mut owned_path = OwnedValuePath::root();
226.         let mut coalesce = vec![];
227.         for segment in self.segment_iter() {
228.             match segment {
229.                 BorrowedSegment::Invalid => return Err(()),
230.                 BorrowedSegment::Index(i) => owned_path.push(OwnedSegment::Index(i)),
231.                 BorrowedSegment::Field(field) => {
232.                     owned_path.push(OwnedSegment::Field(field.to_string()))
233.                 }
234.                 BorrowedSegment::CoalesceField(field) => {
235.                     coalesce.push(field.to_string());
236.                 }
237.                 BorrowedSegment::CoalesceEnd(field) => {
238.                     coalesce.push(field.to_string());
239.                     owned_path.push(OwnedSegment::Coalesce(std::mem::take(&mut coalesce)));
240.                 }
241.             }
242.         }
243.         Ok(owned_path)
244.     }
245. }
