 #[serde(try_from = "String", into = "String")]
 pub enum TimeZone {
     /// System local timezone.
     #[default]
     Local,

     /// A named timezone.
     ///
     /// Must be a valid name in the [TZ database][tzdb].
     ///
     /// [tzdb]: https://en.wikipedia.org/wiki/List_of_tz_database_time_zones
     Named(Tz),
