221. fn format_has_zone(fmt: &str) -> bool {
222.     fmt.contains("%Z")
223.         || fmt.contains("%z")
224.         || fmt.contains("%:z")
225.         || fmt.contains("%#z")
226.         || fmt.contains("%+")
227. }
