229. /// The list of allowed "automatic" timestamp formats with assumed local time zone
230. const TIMESTAMP_LOCAL_FORMATS: &[&str] = &[
231.     "%F %T",           // YYYY-MM-DD HH:MM:SS
232.     "%v %T",           // DD-Mmm-YYYY HH:MM:SS
233.     "%FT%T",           // ISO 8601 / RFC 3339 without TZ
234.     "%m/%d/%Y:%T",     // ???
235.     "%a, %d %b %Y %T", // RFC 822/2822 without TZ
236.     "%a %d %b %T %Y",  // `date` command output without TZ
237.     "%A %d %B %T %Y",  // `date` command output without TZ, long names
238.     "%a %b %e %T %Y",  // ctime format
239. ];
240. 
241. /// The list of allowed "automatic" timestamp formats for UTC
242. const TIMESTAMP_UTC_FORMATS: &[&str] = &[
243.     "%s",     // UNIX timestamp
244.     "%FT%TZ", // ISO 8601 / RFC 3339 UTC
245. ];
246. 
247. /// The list of allowed "automatic" timestamp formats with time zones
248. const TIMESTAMP_TZ_FORMATS: &[&str] = &[
249.     "%+",                 // ISO 8601 / RFC 3339
250.     "%a %d %b %T %Z %Y",  // `date` command output
251.     "%a %d %b %T %z %Y",  // `date` command output, numeric TZ
252.     "%a %d %b %T %#z %Y", // `date` command output, numeric TZ
253.     "%d/%b/%Y:%T %z",     // Common Log
254. ];
