257. ///
258. /// # Errors
259. ///
260. /// Returns an error if the string could not be matched by one of the
261. /// predefined timestamp formats.
262. fn parse_timestamp(tz: TimeZone, s: &str) -> Result<DateTime<Utc>, Error> {
263.     for format in TIMESTAMP_LOCAL_FORMATS {
264.         if let Ok(result) = tz.datetime_from_str(s, format) {
265.             return Ok(result);
266.         }
267.     }
268.     for format in TIMESTAMP_UTC_FORMATS {
269.         if let Ok(result) = Utc.datetime_from_str(s, format) {
270.             return Ok(result);
271.         }
272.     }
273.     if let Ok(result) = DateTime::parse_from_rfc3339(s) {
274.         return Ok(datetime_to_utc(&result));
275.     }
276.     if let Ok(result) = DateTime::parse_from_rfc2822(s) {
277.         return Ok(datetime_to_utc(&result));
278.     }
279.     for format in TIMESTAMP_TZ_FORMATS {
280.         if let Ok(result) = DateTime::parse_from_str(s, format) {
281.             return Ok(datetime_to_utc(&result));
282.         }
283.     }
284.     Err(Error::AutoTimestampParse { s: s.into() })
285. }
